with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , INST_DATE as DUE_DATE
        , INST_PAID_AMT as PAID_AMOUNT
        , NEXT_INST_AMT as INSTALMENT_AMOUNT
        , INST_TOTAL_PENDING_AMT as OUTSTANDING_AFTER_INSTALMENT
        , 'BA_HCP_DT_PREMIUM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_premium') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then DUE_DATE end) as DUE_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then PAID_AMOUNT end) as PAID_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTALMENT_AMOUNT end) as INSTALMENT_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OUTSTANDING_AFTER_INSTALMENT end) as OUTSTANDING_AFTER_INSTALMENT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when DUE_DATE is not null or PAID_AMOUNT is not null or INSTALMENT_AMOUNT is not null or OUTSTANDING_AFTER_INSTALMENT is not null
                     then md5(upper(coalesce(cast(DUE_DATE as varchar), '') || '|' || coalesce(cast(PAID_AMOUNT as varchar), '') || '|' || coalesce(cast(INSTALMENT_AMOUNT as varchar), '') || '|' || coalesce(cast(OUTSTANDING_AFTER_INSTALMENT as varchar), '')))
                end as SAT_POLICY_INSTALMENT_SCHEDULE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_INSTALMENT_SCHEDULE_HASHDIFF is not null
